#!/usr/bin/env python3"""Скрипт для обновления аватаров пользователей"""import sysimport os# Добавляем родительскую директорию в путь Pythonparent_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))sys.path.insert(0, parent_dir)from sqlmodel import Session, selectfrom core.database import enginefrom models.user import User# Примеры URL аватаров для пользователейSAMPLE_AVATARS = [    "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150&h=150&fit=crop&crop=face",    "https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150&h=150&fit=crop&crop=face",    "https://images.unsplash.com/photo-1494790108755-2616b612b786?w=150&h=150&fit=crop&crop=face",    "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=150&h=150&fit=crop&crop=face",    "https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150&h=150&fit=crop&crop=face",    "https://images.unsplash.com/photo-1527980965255-d3b416303d12?w=150&h=150&fit=crop&crop=face",    "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150&h=150&fit=crop&crop=face",    "https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150&h=150&fit=crop&crop=face"]def update_user_avatars():    """Обновить аватары пользователей"""        with Session(engine) as session:        print("=" * 80)        print("👤 ОБНОВЛЕНИЕ АВАТАРОВ ПОЛЬЗОВАТЕЛЕЙ")        print("=" * 80)                # Получаем всех пользователей        users = session.exec(select(User)).all()                if not users:            print("❌ Пользователи не найдены в базе данных")            return                print(f"Найдено {len(users)} пользователей:")        for user in users:            print(f"- {user.username} (ID: {user.id})")                print("\n" + "=" * 50)        print("ОБНОВЛЕНИЕ АВАТАРОВ:")        print("=" * 50)                updated_count = 0                for i, user in enumerate(users):            if not user.avatar_url:  # Обновляем только пользователей без аватара                # Выбираем аватар по индексу пользователя                avatar_url = SAMPLE_AVATARS[i % len(SAMPLE_AVATARS)]                user.avatar_url = avatar_url                session.add(user)                                print(f"✅ {user.username}:")                print(f"   Новый аватар: {avatar_url}")                updated_count += 1            else:                print(f"⚠️  {user.username}: аватар уже установлен")                if updated_count > 0:            session.commit()            print(f"\n✅ Успешно обновлено {updated_count} аватаров!")        else:            print("\n❌ Ни один аватар не был обновлен")def add_custom_user_avatar():    """Добавить аватар для конкретного пользователя"""        with Session(engine) as session:        users = session.exec(select(User)).all()                print("=" * 80)        print("➕ ДОБАВЛЕНИЕ АВАТАРА ДЛЯ ПОЛЬЗОВАТЕЛЯ")        print("=" * 80)                # Показываем список пользователей        for i, user in enumerate(users, 1):            avatar_status = "📷" if user.avatar_url else "❌"            print(f"{i}. {avatar_status} {user.username} (ID: {user.id})")            if user.avatar_url:                print(f"   Текущий аватар: {user.avatar_url}")                try:            choice = int(input(f"\nВыберите пользователя для обновления аватара (1-{len(users)}): "))            if 1 <= choice <= len(users):                selected_user = users[choice - 1]                                print(f"\nТекущий аватар для {selected_user.username}:")                if selected_user.avatar_url:                    print(f"URL: {selected_user.avatar_url}")                else:                    print("Аватар не установлен")                                print("\nПримеры URL аватаров:")                for i, avatar in enumerate(SAMPLE_AVATARS[:5], 1):                    print(f"{i}. {avatar}")                                new_avatar_url = input(f"\nВведите новый URL аватара для {selected_user.username} (или Enter для удаления): ").strip()                                selected_user.avatar_url = new_avatar_url if new_avatar_url else None                session.add(selected_user)                session.commit()                                if new_avatar_url:                    print(f"✅ Аватар для {selected_user.username} обновлен!")                else:                    print(f"✅ Аватар для {selected_user.username} удален!")            else:                print("❌ Неверный выбор!")        except ValueError:            print("❌ Введите корректный номер!")        except Exception as e:            print(f"❌ Ошибка: {e}")def view_current_avatars():    """Просмотреть текущие аватары пользователей"""        with Session(engine) as session:        users = session.exec(select(User)).all()                print("\n" + "=" * 80)        print("📷 ТЕКУЩИЕ АВАТАРЫ ПОЛЬЗОВАТЕЛЕЙ")        print("=" * 80)                for user in users:            print(f"\n👤 {user.username} (ID: {user.id})")            if user.avatar_url:                print(f"   📷 Аватар: {user.avatar_url}")            else:                print(f"   ❌ Аватар не установлен")                print(f"\nВсего пользователей: {len(users)}")def main():    """Главное меню"""        while True:        print("\n" + "=" * 80)        print("👤 УПРАВЛЕНИЕ АВАТАРАМИ ПОЛЬЗОВАТЕЛЕЙ")        print("=" * 80)        print("1. Обновить все аватары пользователей")        print("2. Добавить/изменить аватар для пользователя")        print("3. Просмотреть текущие аватары")        print("4. Выход")                choice = input("\nВыберите действие (1-4): ").strip()                if choice == "1":            update_user_avatars()        elif choice == "2":            add_custom_user_avatar()        elif choice == "3":            view_current_avatars()        elif choice == "4":            print("👋 До свидания!")            break        else:            print("❌ Неверный выбор")if __name__ == "__main__":    main()